globalCSS:
/* ==========================================================
 * Sola Ember (Obsidian Cosmic) — Custom CSS for Lumiverse
 * Canonical 16-Color Palette Integration
 * ========================================================== */

:root {
  /* Sola Canonical Gradients */
  --sola-solstice: linear-gradient(135deg, #F4A261 0%, #EE6C4D 100%);
  --sola-hearth: linear-gradient(135deg, #E07A5F 0%, #C06C54 100%);
  --sola-dusk: linear-gradient(135deg, #F3B74B 0%, #8592E6 100%);
  --sola-starlight: linear-gradient(135deg, #98B9C7 0%, #8592E6 100%);

  /* Text Selection */
  --sola-selection-bg: rgba(133, 146, 230, 0.35);
  --sola-selection-text: #F2F4F8;
}

/* Atmospheric Selection */
::selection {
  background: var(--sola-selection-bg);
  color: var(--sola-selection-text);
}

/* Sola Smooth Scrollbar */
::-webkit-scrollbar {
  width: 7px;
  height: 7px;
}
::-webkit-scrollbar-track {
  background: transparent;
}
::-webkit-scrollbar-thumb {
  background: rgba(143, 164, 178, 0.28);
  border-radius: 9999px;
  border: 1px solid rgba(133, 146, 230, 0.15);
}
::-webkit-scrollbar-thumb:hover {
  background: rgba(133, 146, 230, 0.5);
}

/* Sola Dialogue & Thoughts Highlight Invariants */
.prose em,
[data-component="MessageContent"] em {
  color: #98B9C7 !important; /* Mist Interiority */
  font-style: italic;
}

.prose q,
.proseDialogue,
[data-component="MessageContent"] q {
  color: #7A8B99 !important; /* Denim Dialogue */
}

.prose blockquote {
  border-left: 3px solid #8FA4B2 !important;
  background: rgba(143, 164, 178, 0.06);
  padding: 8px 14px;
  border-radius: 0 8px 8px 0;
  color: rgba(242, 244, 248, 0.85);
}

/* Starlight Radiant CTA Buttons */
button[data-variant="primary"],
.btnPrimary {
  background: linear-gradient(135deg, #98B9C7 0%, #8592E6 100%) !important;
  color: #0E0C13 !important;
  font-weight: 600;
  border: 1px solid rgba(152, 185, 199, 0.3) !important;
  box-shadow: 0 2px 12px rgba(133, 146, 230, 0.25) !important;
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}

button[data-variant="primary"]:hover,
.btnPrimary:hover {
  background: linear-gradient(135deg, #A8C4D0 0%, #95A0EC 100%) !important;
  box-shadow: 0 4px 18px rgba(133, 146, 230, 0.42) !important;
  transform: translateY(-1px);
}

/* Focus Rings */
:focus-visible {
  outline: 2px solid rgba(133, 146, 230, 0.6) !important;
  outline-offset: 2px;
}
